import{_ as r,c as s,o as a,ah as t,j as e,a as i}from"./chunks/framework.CAZQ2vdu.js";const d="/Qonnectra-docs/pr-17/images/manual/teil-a/model_objects.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/model_conduit_microducts.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/model_cable_fibers.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/model_node_ports.jpg",u="/Qonnectra-docs/pr-17/videos/model_node_component.webm",g="/Qonnectra-docs/pr-17/images/manual/teil-a/model_address_units.jpg",m="/Qonnectra-docs/pr-17/images/manual/teil-a/model_area.jpg",c="/Qonnectra-docs/pr-17/images/manual/teil-a/model_flag.jpg",b="/Qonnectra-docs/pr-17/images/manual/teil-a/model_master_data.jpg",A=JSON.parse('{"title":"2. Grundbegriffe und Datenmodell","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.md","filePath":"manual/teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.md"}'),p={name:"manual/teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.md"};function f(k,n,z,w,S,K){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="_2-grundbegriffe-und-datenmodell" tabindex="-1">2. Grundbegriffe und Datenmodell <a class="header-anchor" href="#_2-grundbegriffe-und-datenmodell" aria-label="Permalink to &quot;2. Grundbegriffe und Datenmodell&quot;">​</a></h1><p>Qonnectra beschreibt ein Glasfasernetz nicht als Zeichnung, sondern als Sammlung von Objekten, die ineinanderstecken: Im Graben liegen Rohre, in den Rohren Mikrorohre, in den Mikrorohren Kabel, in den Kabeln Bündel und Fasern. Dieses Kapitel erklärt diese Objekte und ihre Beziehungen einmal zusammenhängend. Die Kapitel 4 bis 17 setzen die Begriffe voraus und beschreiben nur noch, wo Sie sie erfassen und auswerten.</p><p>Alle Objekte gehören zu genau einem <strong>Projekt</strong>, das Sie oben links in der Kopfzeile auswählen, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>. Eine Auswertung über mehrere Projekte hinweg gibt es nur in der Karte und in der Wertermittlung.</p><p>Vier Objektarten haben eine Lage im Raum und erscheinen deshalb in der Karte: die <strong>Trasse</strong> als Linie, der <strong>Netzknoten</strong> und die <strong>Adresse</strong> als Punkt und das <strong>Gebiet</strong> als Fläche. Alles andere hängt an diesen vier.</p><p><img src="'+d+'" alt="Screenshot der Karte mit Trassen als blauen Linien, Netzknoten als Quadraten, Adressen als orangen Punkten und dem grün eingefärbten Projektgebiet" data-zoomable="true"></p><h2 id="_2-1-trasse-rohr-und-mikrorohr" tabindex="-1">2.1 Trasse, Rohr und Mikrorohr <a class="header-anchor" href="#_2-1-trasse-rohr-und-mikrorohr" aria-label="Permalink to &quot;2.1 Trasse, Rohr und Mikrorohr&quot;">​</a></h2><p>Eine <strong>Trasse</strong> ist ein einzelner Grabenabschnitt mit einer eigenen Trassen-ID, etwa „TR-W55WVN3“. Sie ist die kleinste Baueinheit des Netzes: Alle Angaben einer Trasse gelten für ihre gesamte Länge – wo Bauart, Oberfläche oder Verlegetiefe wechseln, sind es zwei Trassen. Die Trassen-ID ist innerhalb eines Projekts eindeutig. Dieses Handbuch nennt eine einzelne Trasse dort <strong>Trassensegment</strong>, wo es auf die Abgrenzung ankommt – vor allem in der Rohrzuordnung, siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>.</p><p>An einer Trasse hinterlegt sind unter anderem Oberfläche, Bauart, Verlegetiefe, Status, Phase, Eigentümer, Baufirma und Datum sowie die Ja-Nein-Angaben „Hausanschluss“, „Eigenleistung“ und „Förderstatus“, nach denen das Dashboard auswertet (siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>).</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Länge einer Trasse geben Sie nicht ein – Qonnectra berechnet sie aus der Geometrie. Gezeichnet werden Trassen in QGIS, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>.</p></div><p>Ein <strong>Rohr</strong> (Leerrohr) hat einen Namen, der innerhalb des Projekts eindeutig ist, und einen <strong>Rohrtyp</strong>. Der Rohrtyp beschreibt den Aufbau: „12x10/6“ steht für zwölf Mikrorohre der Größe 10/6 – Außen- und Innendurchmesser in Millimetern –, „16/12“ für ein einzelnes Rohr ohne Unterteilung. Liegt das Rohr in einem weiteren Rohr, steht dieses im Feld „Schutzrohr“.</p><p>Ein Rohr hat <strong>keine eigene Geometrie</strong>. Wo es verläuft, ergibt sich aus den Trassensegmenten, denen es zugeordnet ist. Diese Zuordnung ist beidseitig mehrfach: Ein Rohr läuft über mehrere Trassensegmente, und ein Trassensegment führt mehrere Rohre. Deshalb hat der Kartenlayer „Rohr“ auch nur Beschriftungen und keine eigene Darstellung, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>.</p><p>Die <strong>Mikrorohre</strong> eines Rohrs entstehen automatisch beim Anlegen, und zwar aus dem Rohrtyp: Er gibt ihre Anzahl und ihre Farben vor. Jedes Mikrorohr hat eine durchlaufende Nummer, eine Farbe und einen Status, der auf „Intakt“ steht, solange nichts anderes eingetragen ist. Zusätzlich kann an einem Mikrorohr hinterlegt sein, zu welcher Adresse es führt und welches Kabel darin liegt.</p><p><img src="'+o+'" alt="Screenshot der Ansicht „Mikrorohre“ mit der Info-Box rechts: das aufgeklappte Rohr St-V02-01 und die Liste seiner zwölf Mikrorohre mit Farbe, Adresse, Kabel und Status" class="big" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Anzahl und Farben der Mikrorohre lassen sich nachträglich nicht ändern. Sie richten sich nach dem Rohrtyp zum Zeitpunkt des Anlegens; ein später geänderter Rohrtyp lässt die Liste unverändert, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-4-mikrorohre-eines-rohrs">Mikrorohre eines Rohrs</a>.</p></div><h2 id="_2-2-kabel-bundel-faser-und-spleiß" tabindex="-1">2.2 Kabel, Bündel, Faser und Spleiß <a class="header-anchor" href="#_2-2-kabel-bundel-faser-und-spleiß" aria-label="Permalink to &quot;2.2 Kabel, Bündel, Faser und Spleiß&quot;">​</a></h2><p>Ein <strong>Kabel</strong> hat einen Namen, einen <strong>Kabeltyp</strong> und je einen Netzknoten als Anfang und Ende. Der Kabeltyp beschreibt den Aufbau: „LTMC288(12x24)“ steht für 288 Fasern, aufgeteilt in zwölf <strong>Bündel</strong> mit je 24 <strong>Fasern</strong>.</p><p>Wie ein Rohr hat ein Kabel keine eigene Geometrie. Es liegt in einem oder mehreren Mikrorohren, und aus deren Rohren und den Trassensegmenten dieser Rohre ergibt sich der Weg des Kabels. Die Verknüpfung stellen Sie im Netzschema her, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Auch die Länge eines Kabels ist berechnet und nicht eingegeben: Qonnectra ermittelt den kürzesten Weg zwischen Anfangs- und Endknoten über die Trassensegmente, in denen das Kabel liegt. Die Angaben „Reserve am Anfang“, „Reserve am Ende“ und „Reserve auf der Strecke“ geben Sie dagegen selbst ein; sie ergeben zusammen mit der Länge die „Gesamtlänge“.</p></div><p>Die Fasern eines Kabels entstehen wie die Mikrorohre eines Rohrs automatisch aus dem Kabeltyp. Jede Faser gehört zu einem Bündel und trägt vier Angaben, die sie eindeutig machen: die Nummer und die Farbe ihres Bündels sowie ihre eigene Nummer und Farbe. Die Nummer läuft über das ganze Kabel durch, die Farben wiederholen sich in jedem Bündel. Dazu kommt ein Status, der wie beim Mikrorohr auf „Intakt“ steht, solange nichts anderes eingetragen ist.</p><p><img src="'+l+'" alt="Screenshot des Netzschemas mit der Info-Box rechts: das Kabel St-S01-288-Fs im Reiter „Status“, darin das aufgeklappte Bündel 1 mit seinen Fasern samt Nummer, Farbe und Status" class="big" data-zoomable="true"></p><p>Ein <strong>Spleiß</strong> ist die Verbindung zweier Fasern. Er liegt nicht am Kabel, sondern in einem Netzknoten – genauer an einem Port einer Komponente, die dort eingebaut ist, siehe Abschnitt <a href="#_2-3-netzknoten-container-slots-komponenten-und-ports">Netzknoten, Container, Slots, Komponenten und Ports</a>. Erst die Kette aus Kabeln und Spleißen ergibt einen durchgehenden Weg von der Faser im Verteiler bis zur Wohneinheit; ermitteln lässt er sich im Faserweg, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Kabelnamen müssen in der gesamten Installation eindeutig sein, nicht nur innerhalb des Projekts. Bei Rohren und Netzknoten genügt Eindeutigkeit im Projekt. Ein Kabelname, den es in einem anderen Projekt schon gibt, wird deshalb abgewiesen.</p></div><h2 id="_2-3-netzknoten-container-slots-komponenten-und-ports" tabindex="-1">2.3 Netzknoten, Container, Slots, Komponenten und Ports <a class="header-anchor" href="#_2-3-netzknoten-container-slots-komponenten-und-ports" aria-label="Permalink to &quot;2.3 Netzknoten, Container, Slots, Komponenten und Ports&quot;">​</a></h2><p>Ein <strong>Netzknoten</strong> ist ein Punkt im Netz, an dem Trassen zusammenlaufen und Kabel beginnen, enden oder verbunden werden. Er hat einen Namen, der innerhalb des Projekts eindeutig ist, und einen <strong>Netzknotentyp</strong> – etwa „Hausanschluss“, „Muffe“, „MFG“, „NVt 48“ oder „Kabelring“. Optional sind eine Adresse, Eigentümer, Baufirma, Hersteller und ein Datum sowie die Gewährleistungsfrist, die das Dashboard überwacht (siehe Abschnitt <a href="./04-dashboard.html#_4-7-gewahrleistungsfristen-im-blick-behalten">Gewährleistungsfristen im Blick behalten</a>).</p><p>Netzknoten können einander untergeordnet sein: Das Feld „Übergeordneter Netzknoten“ hängt einen Knoten unter einen anderen, etwa alle Hausanschlüsse unter den Verteiler, der sie versorgt. Das Netzschema nutzt diese Über- und Unterordnung, um ein großes Netz auf mehrere Ebenen zu verteilen, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>.</p><p>Der innere Aufbau eines Netzknotens ist in vier Stufen von außen nach innen beschrieben:</p><ul><li><strong>Container</strong> – eine Gruppe von Slot-Konfigurationen, etwa ein Rack oder eine Gehäusetür. Container sind optional und können ineinander liegen; ihre Typen richtet die Administration ein, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</li><li><strong>Slot-Konfiguration</strong> – je Einbauseite eines Netzknotens eine Konfiguration mit einem Namen („A“, „B“) und einer Anzahl von Gesamtslots. Ein <strong>Slot</strong> ist ein einzelner Einbauplatz; die <strong>Clip-Nummer</strong>, mit der das Slot-Grid ihn beschriftet, hängt an ihm und nicht an der Komponente, die dort sitzt.</li><li><strong>Komponente</strong> – das Bauteil, das in den Slots sitzt: eine Spleißkassette, ein Splitter, ein Patchfeld. Der Komponententyp gibt vor, wie viele Slots das Bauteil belegt – eine Spleißkassette einen, ein „Splitter 1:8“ zwei, ein „4HE (12xLC-APC)“ vier.</li><li><strong>Port</strong> – ein Anschluss an der Komponente. Wie viele Ports eine Komponente hat, gibt ebenfalls der Komponententyp vor. Jeder Port verbindet eine Faser auf der Seite A mit einer Faser auf der Seite B – das ist der Spleiß aus Abschnitt <a href="#_2-2-kabel-bundel-faser-und-spleiß">Kabel, Bündel, Faser und Spleiß</a>. Ports ohne Spleiß bleiben leer.</li></ul><p><img src="'+h+'" alt="Screenshot des maximierten Fensters „Netzknotenstruktur“ mit der Komponente „Spleisskassette“ und ihren zwölf Ports: sechs mit je einer Faser auf Seite A und B, sechs leer" class="big" data-zoomable="true"></p><p>Das Fenster „Netzknotenstruktur“ zeigt beide Stufen, aber nie gleichzeitig: Ein Klick auf eine Komponente im Slot-Grid führt in ihre Ports, „Zurück“ wieder in das Grid.</p>',29),e("p",null,[e("video",{src:u,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/model_node_component.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),t('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Angelegt und geändert wird der Aufbau eines Netzknotens im Netzschema, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>. Aus der Karte heraus sind Slot-Konfiguration und Struktur reine Anzeigen, siehe Abschnitt <a href="./05-karte.html#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen">Netzknoten: Slot-Konfiguration und Struktur öffnen</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der innere Aufbau ist optional und in vielen Projekten gar nicht erfasst. Ist für einen Netzknoten keine Slot-Konfiguration hinterlegt, meldet das Fenster „Keine Slot-Konfigurationen gefunden“ – der Netzknoten selbst ist dann trotzdem vollständig dokumentiert. Ohne Container erscheinen die Konfigurationen als flache Liste.</p></div><h2 id="_2-4-adresse-und-wohneinheit" tabindex="-1">2.4 Adresse und Wohneinheit <a class="header-anchor" href="#_2-4-adresse-und-wohneinheit" aria-label="Permalink to &quot;2.4 Adresse und Wohneinheit&quot;">​</a></h2><p>Eine <strong>Adresse</strong> ist ein Gebäude als Punkt in der Karte, beschrieben durch Straße, Hausnummer mit Zusatz, Postleitzahl, Ort und Ortsteil. Dazu kommen eine von Qonnectra erzeugte „Adress-ID“, das Feld „Adress-ID 2“ für eine Kennung aus einem anderen System und der <strong>Ausbaustatus</strong>, der den Fortschritt der Erschließung festhält.</p><p>Eine <strong>Wohneinheit</strong> ist eine einzelne Nutzungseinheit in diesem Gebäude – eine Wohnung, ein Ladengeschäft, eine Schule. Sie gehört immer zu einer Adresse und hat eine eigene ID, eine Etage, eine Seite, einen Gebäudeteil, einen Typ und einen Status. Für den Vertrieb lassen sich zusätzlich „Name des Bewohners“, „Erfassungsdatum Bewohner“ und das Datum „Betriebsbereit“ hinterlegen sowie zwei Kennungen aus anderen Systemen.</p><p>Die Adresse ist damit das Bindeglied zwischen Gebäude und Netz. Was auf der Netzseite an ihr hängt, zeigt der Abschnitt „Mikrorohrverbindungen“ in der Adressdetailansicht: das Mikrorohr mit seiner Nummer und Farbe, das Rohr, in dem es liegt, und der Netzknoten, von dem es kommt.</p><p><img src="'+g+'" alt="Screenshot der Adressdetailansicht mit Hervorhebung der Abschnitte „Mikrorohrverbindungen“ und „Wohneinheiten“" class="big" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Wohneinheiten sind die Bezugsgröße für den Ausbaufortschritt. Sie werden im Dashboard nach Ort und Typ ausgewertet (siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>) und lassen sich in der Nachverdichtung je Adresse als PDF ausgeben, siehe Kapitel <a href="./07-nachverdichtung.html">Nachverdichtung</a>.</p></div><h2 id="_2-5-gebiet-und-gebietstyp" tabindex="-1">2.5 Gebiet und Gebietstyp <a class="header-anchor" href="#_2-5-gebiet-und-gebietstyp" aria-label="Permalink to &quot;2.5 Gebiet und Gebietstyp&quot;">​</a></h2><p>Ein <strong>Gebiet</strong> ist eine Fläche mit einem Namen und einem <strong>Gebietstyp</strong>. Es enthält selbst keine Netzdaten, sondern grenzt einen Bereich ab: das Projektgebiet, das Versorgungsgebiet eines Verteilers, die Grundfläche eines Gebäudes. In der Legende der Karte lässt sich der Eintrag „Gebiet“ aufklappen; darunter stehen die Gebietstypen, die Sie einzeln ein- und ausblenden können.</p><p><img src="'+m+'" alt="Screenshot der Karte mit Hervorhebung der Legende oben rechts, in der der Eintrag „Gebiet“ aufgeklappt ist und seine Gebietstypen zeigt; in der Kartenmitte die beiden Projektgebiete" data-zoomable="true"></p><p>Wozu die Abgrenzung dient, zeigt der Reiter „Gebiete“ des Dashboards: Er rechnet aus, welcher Anteil der Adressen, Netzknoten und Wohneinheiten eines Projekts innerhalb der Gebiete liegt, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Fläche eines Projektgebiets liegt unter dem gesamten Netz. Ein Klick in die Karte trifft deshalb leicht das Gebiet statt der Trasse darüber; welche Hilfen es dagegen gibt, beschreibt Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> unter „Objekte anklicken“.</p></div><h2 id="_2-6-kennzeichen-als-projektweiter-filter" tabindex="-1">2.6 Kennzeichen als projektweiter Filter <a class="header-anchor" href="#_2-6-kennzeichen-als-projektweiter-filter" aria-label="Permalink to &quot;2.6 Kennzeichen als projektweiter Filter&quot;">​</a></h2><p>Das <strong>Kennzeichen</strong> ist eine zweite Ordnungsebene neben dem Projekt. Trasse, Rohr, Netzknoten, Kabel, Adresse und Gebiet tragen jeweils genau eines, und es ist ein Pflichtfeld – ein Objekt ohne Kennzeichen lässt sich nicht speichern. Womit Sie es füllen, ist Ihre Entscheidung: verbreitet sind Bauabschnitte, Ausbaucluster oder Ortsteile.</p><p><img src="'+c+'" alt="Screenshot der Rohrverwaltung mit Hervorhebung der Spaltenüberschrift „Kennzeichen“ und ihres Suchfeldes rechts in der Tabelle" data-zoomable="true"></p><p>Eingrenzen können Sie den Bestand darüber an zwei Stellen:</p><ul><li>in der Rohrzuordnung über die Auswahl „Kennzeichen“, die die Rohrliste einschränkt, siehe Abschnitt <a href="./11-rohrzuordnung.html#_11-6-nach-kennzeichen-eingrenzen">Nach Kennzeichen eingrenzen</a></li><li>in der Rohrverwaltung und bei den Adressen über das Suchfeld unter der Spalte „Kennzeichen“, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel">Tabellen</a></li></ul><p>Auch der Excel-Import von Rohren führt eine Spalte „Kennzeichen“. Sie darf in keiner Zeile leer bleiben, sonst scheitert der gesamte Import, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-5-excel-import-vorlage-ablauf-fehlermeldungen">Excel-Import</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Kennzeichen ist kein Projekt. Objekte mit unterschiedlichen Kennzeichen gehören weiterhin zum selben Projekt und erscheinen gemeinsam in der Karte, im Dashboard und in allen Auswertungen. Nur wo eine Ansicht ausdrücklich ein Kennzeichen anbietet, wirkt es als Filter.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Dashboard kennt keinen Filter nach Kennzeichen; seine Kennzahlen beziehen sich immer auf den gesamten Bestand des Projekts, siehe Abschnitt <a href="./04-dashboard.html#_4-8-1-nach-kennzeichen-filtern">Nach Kennzeichen filtern</a>.</p></div><h2 id="_2-7-stammdaten-status-phase-netzebene-firmen" tabindex="-1">2.7 Stammdaten: Status, Phase, Netzebene, Firmen <a class="header-anchor" href="#_2-7-stammdaten-status-phase-netzebene-firmen" aria-label="Permalink to &quot;2.7 Stammdaten: Status, Phase, Netzebene, Firmen&quot;">​</a></h2><p>Viele Angaben wählen Sie nicht frei, sondern aus einer festen Liste. Diese Listen sind die <strong>Stammdaten</strong> der Installation. Wo eine solche Angabe erfasst wird, steht ein Kombinationsfeld, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-2-auswahllisten-und-kombinationsfelder">Auswahllisten und Kombinationsfelder</a>.</p><p><img src="'+b+'" alt="Screenshot der Rohrverwaltung mit Hervorhebung des Feldes „Status“ in der Info-Box und der geöffneten Liste mit den Werten „dokumentiert“, „geplant“ und „im Bau“" data-zoomable="true"></p><p>Die wichtigsten dieser Listen:</p><ul><li><strong>Status</strong> – der Bearbeitungsstand eines Objekts, etwa „geplant“, „im Bau“, „dokumentiert“. Trasse, Rohr, Netzknoten und Kabel nutzen dieselbe Liste.</li><li><strong>Phase</strong> – der Bauabschnitt einer Trasse.</li><li><strong>Netzebene</strong> – die Stufe des Objekts im Netzaufbau, üblicherweise „Netzebene 1“ bis „Netzebene 4“. Rohr, Netzknoten und Kabel tragen sie.</li><li><strong>Firmen</strong> – eine gemeinsame Liste für die drei Rollen „Eigentümer“, „Baufirma“ und „Hersteller“. Zu jeder Firma lassen sich Anschrift, Telefonnummer und E-Mail-Adresse hinterlegen.</li><li><strong>Oberfläche</strong> und <strong>Bauart</strong> einer Trasse. Bei der Oberfläche ist zusätzlich vermerkt, ob sie versiegelt ist – davon hängt die Wertermittlung ab, siehe Kapitel <a href="./09-wertermittlung.html">Wertermittlung</a>.</li><li><strong>Rohrtyp</strong>, <strong>Kabeltyp</strong>, <strong>Netzknotentyp</strong> und <strong>Komponententyp</strong> mit den Angaben, aus denen Qonnectra Mikrorohre, Fasern und Ports erzeugt.</li><li>die Farblisten für Mikrorohre und Fasern, die Statuslisten für Mikrorohre und Fasern, der <strong>Ausbaustatus</strong> einer Adresse, <strong>Typ</strong> und <strong>Status</strong> einer Wohneinheit, der <strong>Gebietstyp</strong> und der <strong>Container-Typ</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Wert, der nicht in der Liste steht, lässt sich nicht eintippen. Fehlt Ihnen eine Firma, ein Rohrtyp oder ein Status, wenden Sie sich an Ihre Administration; gepflegt werden die Listen im Administrationsbereich, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Stammdaten gelten für die gesamte Installation und nicht je Projekt. Ein neuer Rohrtyp steht deshalb sofort in allen Projekten zur Auswahl – auch in denen, für die er nicht gedacht war.</p></div>',28)])])}const v=r(p,[["render",f]]);export{A as __pageData,v as default};
